mapper.select:
SELECT
IFNULL(SUM(actual_quantity), 0) AS actual_quantity,
IFNULL(SUM(actual_mete), 0) AS actual_mete,
IFNULL(SUM(actual_total_area), 0) AS actual_total_area
FROM project_install_summary
WHERE bool_delete_enum = 0

    AND project_id = #{projectId}


    AND monomer_id = #{monomerId}


    AND area_id = #{areaId}


    AND product_type = #{productType}


    AND category = #{category}

SELECT temp_table.*, temp_table.monomer_id as 'monomer.id', m.name as 'monomer.name', temp_table.area_id as 'area.id', area.name as 'area.name' FROM (
SELECT a.id product_id, 2 product_type, a.monomer_id, a.area_id, a.name, a.serial_number, a.quantity, IFNULL( pis.actual_quantity, 0 ) AS install_quantity, ( CASE IFNULL( pis.actual_quantity, 0 ) WHEN 0 THEN 1 WHEN a.quantity THEN 4 ELSE 2 END ) AS install_status FROM tech_artifact AS a LEFT JOIN project_install_summary AS pis ON a.id = pis.product_id AND pis.product_type = 2 AND a.project_id = pis.project_id AND pis.bool_delete_enum = 0
SELECT a.id product_id, 4 product_type, a.category, null as monomer_id, null as area_id, a.name, a.serial_number, a.quantity, IFNULL( pis.actual_quantity, 0 ) AS install_quantity, ( CASE IFNULL( pis.actual_quantity, 0 ) WHEN 0 THEN 1 WHEN a.quantity THEN 4 ELSE 2 END ) AS install_status FROM tech_enclosure AS a LEFT JOIN project_install_summary AS pis ON a.id = pis.product_id AND pis.product_type = 4 AND pis.bool_delete_enum = 0
SELECT a.id product_id, 8 product_type, a.monomer_id, a.area_id, a.name, a.quantity, IFNULL( pis.actual_quantity, 0 ) AS install_quantity, ( CASE IFNULL( pis.actual_quantity, 0 ) WHEN 0 THEN 1 WHEN a.quantity THEN 4 ELSE 2 END ) install_status FROM tech_standard_part AS a LEFT JOIN project_install_summary AS pis ON a.id = pis.product_id AND pis.product_type = 8 AND pis.bool_delete_enum = 0
WHERE a.bool_delete_enum = 0 AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.category = #{category}
AND a.area_id = #{areaId}
AND a.enclosure_plan_id = #{areaId}
and a.name like concat('%',#{name},'%')
and a.serial_number like concat('%',#{serialNumber},'%')
) as temp_table left join plan_monomer as m on m.id = temp_table.monomer_id and m.bool_delete_enum = 0 left join plan_area as area on area.id = temp_table.area_id and temp_table.product_type != 4 and area.bool_delete_enum = 0 left join enclosure_plan as ep on ep.id = temp_table.area_id and temp_table.product_type = 4 and ep.bool_delete_enum = 0
temp_table.install_status = #{installStatus}

SELECT temp_table.*, temp_table.monomer_id as 'monomer.id', m.name as 'monomer.name', temp_table.area_id as 'area.id', area.name as 'area.name' FROM (
SELECT a.id product_id, 2 product_type, a.monomer_id, a.area_id, a.name, a.serial_number, a.quantity, IFNULL( pis.actual_quantity, 0 ) AS install_quantity, ( CASE IFNULL( pis.actual_quantity, 0 ) WHEN 0 THEN 1 WHEN a.quantity THEN 4 ELSE 2 END ) AS install_status FROM tech_artifact AS a LEFT JOIN project_install_summary AS pis ON a.id = pis.product_id AND pis.product_type = 2 AND a.project_id = pis.project_id AND pis.bool_delete_enum = 0
SELECT a.id product_id, 4 product_type, a.category, null as monomer_id, null as area_id, a.name, a.serial_number, a.quantity, IFNULL( pis.actual_quantity, 0 ) AS install_quantity, ( CASE IFNULL( pis.actual_quantity, 0 ) WHEN 0 THEN 1 WHEN a.quantity THEN 4 ELSE 2 END ) AS install_status FROM tech_enclosure AS a LEFT JOIN project_install_summary AS pis ON a.id = pis.product_id AND pis.product_type = 4 AND pis.bool_delete_enum = 0
SELECT a.id product_id, 8 product_type, a.monomer_id, a.area_id, a.name, a.quantity, IFNULL( pis.actual_quantity, 0 ) AS install_quantity, ( CASE IFNULL( pis.actual_quantity, 0 ) WHEN 0 THEN 1 WHEN a.quantity THEN 4 ELSE 2 END ) install_status FROM tech_standard_part AS a LEFT JOIN project_install_summary AS pis ON a.id = pis.product_id AND pis.product_type = 8 AND pis.bool_delete_enum = 0
WHERE a.bool_delete_enum = 0 AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
and a.name like concat('%',#{name},'%')
and a.serial_number like concat('%',#{serialNumber},'%')
) as temp_table left join plan_monomer as m on m.id = temp_table.monomer_id and m.bool_delete_enum = 0 left join plan_area as area on area.id = temp_table.area_id and temp_table.product_type != 4 and area.bool_delete_enum = 0 left join enclosure_plan as ep on ep.id = temp_table.area_id and temp_table.product_type = 4 and ep.bool_delete_enum = 0
temp_table.install_status = #{installStatus}
